"""Ordered offline-edit queue and reconnect replay."""

from __future__ import annotations

from dataclasses import dataclass
from threading import RLock
from typing import Callable

from models import record as record_model


PRESERVES = "local creation order only"
STREAM_LINK = "offline.edits"


@dataclass(frozen=True)
class RejectedEdit:
    edit: record_model.OfflineEdit
    reason: str


@dataclass(frozen=True)
class SyncResult:
    applied_edit_ids: tuple[str, ...] = ()
    rejected: tuple[RejectedEdit, ...] = ()
    pending_count: int = 0
    interrupted_by: Exception | None = None


class OfflineEditQueue:
    """Replay pending edits on the offline-to-online transition."""

    def __init__(self) -> None:
        self._pending: list[record_model.OfflineEdit] = []
        self._rejected: list[RejectedEdit] = []
        self._connected = False
        self._lock = RLock()

    def enqueue(self, edit: record_model.OfflineEdit) -> None:
        with self._lock:
            self._pending.append(edit)

    @property
    def pending(self) -> tuple[record_model.OfflineEdit, ...]:
        with self._lock:
            return tuple(self._pending)

    @property
    def rejected(self) -> tuple[RejectedEdit, ...]:
        with self._lock:
            return tuple(self._rejected)

    def on_connectivity_changed(
        self,
        connected: bool,
        store: record_model.RecordStore,
        *,
        apply: Callable[
            [record_model.RecordStore, record_model.OfflineEdit],
            record_model.Record,
        ] = record_model.apply_offline_edit,
    ) -> SyncResult:
        """Drain once when the app transitions from offline to connected."""

        with self._lock:
            was_connected = self._connected
            self._connected = connected

        if not connected or was_connected:
            return SyncResult(pending_count=len(self.pending))
        return self.sync(store, apply=apply)

    def sync(
        self,
        store: record_model.RecordStore,
        *,
        apply: Callable[
            [record_model.RecordStore, record_model.OfflineEdit],
            record_model.Record,
        ] = record_model.apply_offline_edit,
    ) -> SyncResult:
        """Synchronize in enqueue order, acknowledging only handled edits."""

        applied: list[str] = []
        rejected: list[RejectedEdit] = []

        while True:
            with self._lock:
                if not self._pending:
                    break
                edit = self._pending[0]

            try:
                apply(store, edit)
            except record_model.TombstonedRecordError as exc:
                rejection = RejectedEdit(edit=edit, reason=str(exc))
                with self._lock:
                    if self._pending and self._pending[0] is edit:
                        self._pending.pop(0)
                    self._rejected.append(rejection)
                rejected.append(rejection)
            except Exception as exc:
                return SyncResult(
                    applied_edit_ids=tuple(applied),
                    rejected=tuple(rejected),
                    pending_count=len(self.pending),
                    interrupted_by=exc,
                )
            else:
                with self._lock:
                    if self._pending and self._pending[0] is edit:
                        self._pending.pop(0)
                applied.append(edit.edit_id)

        return SyncResult(
            applied_edit_ids=tuple(applied),
            rejected=tuple(rejected),
            pending_count=0,
        )
"""Record mutation boundary, including replayed offline edits."""

from __future__ import annotations

from dataclasses import dataclass, field
from datetime import datetime, timezone
from threading import RLock
from typing import Any, Callable, Mapping

from server.tombstones import TombstoneStore


STREAM = "offline.edits"
STAMPED = "updated_at"


def _now() -> datetime:
    return datetime.now(timezone.utc)


@dataclass(frozen=True)
class OfflineEdit:
    edit_id: str
    record_id: str
    changes: Mapping[str, Any]
    created_at: datetime

    def __post_init__(self) -> None:
        if not self.edit_id or not self.record_id:
            raise ValueError("edit_id and record_id are required")
        if self.created_at.tzinfo is None:
            raise ValueError("created_at must be timezone-aware")
        object.__setattr__(self, "changes", dict(self.changes))


@dataclass
class Record:
    record_id: str
    values: dict[str, Any] = field(default_factory=dict)
    updated_at: datetime | None = None


class TombstonedRecordError(RuntimeError):
    """Raised when an offline update targets a deleted record."""


class RecordStore:
    def __init__(self, *, tombstones: TombstoneStore | None = None) -> None:
        self.records: dict[str, Record] = {}
        self.tombstones = tombstones or TombstoneStore()
        self._applied_edits: dict[str, Record] = {}
        self._lock = RLock()


def apply_offline_edit(
    store: RecordStore,
    edit: OfflineEdit,
    *,
    clock: Callable[[], datetime] = _now,
) -> Record:
    """Apply one queued edit idempotently and stamp ``updated_at`` here.

    This module-level function is the single replay boundary used by the
    reconnect queue. A retried edit ID returns its original result without
    applying the mutation or generating a second timestamp.
    """

    with store._lock:
        applied = store._applied_edits.get(edit.edit_id)
        if applied is not None:
            return applied

        if store.tombstones.blocks_update(edit.record_id):
            raise TombstonedRecordError(
                f"offline edit {edit.edit_id!r} targets deleted record "
                f"{edit.record_id!r}"
            )

        stamped_at = clock()
        if stamped_at.tzinfo is None:
            raise ValueError("clock must return a timezone-aware timestamp")

        current = store.records.get(edit.record_id)
        values = dict(current.values) if current is not None else {}
        values.update(edit.changes)
        record = Record(
            record_id=edit.record_id,
            values=values,
            updated_at=stamped_at.astimezone(timezone.utc),
        )
        store.records[edit.record_id] = record
        store._applied_edits[edit.edit_id] = record
        return record
"""Server-side deletion tracking used while replaying offline edits."""

from __future__ import annotations

from dataclasses import dataclass
from datetime import datetime, timedelta, timezone
from threading import RLock


TOMBSTONE_HOURS = 24
STREAM_REF = "offline.edits"


def _utc(value: datetime) -> datetime:
    if value.tzinfo is None:
        raise ValueError("timestamps must be timezone-aware")
    return value.astimezone(timezone.utc)


@dataclass(frozen=True)
class Tombstone:
    record_id: str
    deleted_at: datetime

    @property
    def expires_at(self) -> datetime:
        return self.deleted_at + timedelta(hours=TOMBSTONE_HOURS)


class TombstoneStore:
    """Keep active tombstones plus a durable deletion barrier.

    Active tombstones expire after 24 hours. The lightweight deletion barrier
    remains so an offline update cannot become an implicit create merely
    because the full tombstone expired.
    """

    def __init__(self) -> None:
        self._active: dict[str, Tombstone] = {}
        self._deleted_ids: set[str] = set()
        self._lock = RLock()

    def add(self, record_id: str, *, deleted_at: datetime) -> Tombstone:
        tombstone = Tombstone(record_id=record_id, deleted_at=_utc(deleted_at))
        with self._lock:
            self._active[record_id] = tombstone
            self._deleted_ids.add(record_id)
        return tombstone

    def blocks_update(self, record_id: str) -> bool:
        """Return whether an offline update must not recreate this record."""

        with self._lock:
            return record_id in self._deleted_ids

    def is_active(self, record_id: str, *, now: datetime) -> bool:
        with self._lock:
            tombstone = self._active.get(record_id)
            return tombstone is not None and _utc(now) < tombstone.expires_at

    def purge_expired(self, *, now: datetime) -> int:
        """Drop expired full tombstones without dropping deletion barriers."""

        cutoff = _utc(now)
        with self._lock:
            expired = [
                record_id
                for record_id, tombstone in self._active.items()
                if cutoff >= tombstone.expires_at
            ]
            for record_id in expired:
                del self._active[record_id]
            return len(expired)
